window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["self-supervised-learning"]={"title":"自监督学习：让数据自己产生训练目标","subtitle":"统一理解自回归、遮盖重建、对比学习与自蒸馏，并追踪预文本目标怎样迁移、走捷径或错位。","thesis":"自监督学习不是“没有监督”，而是由数据及其变换自动构造输入—目标对。它把海量未人工标注数据变成训练信号，先学习可迁移表示或生成能力；但<b>预文本损失只是下游语义、事实性与行为目标的代理</b>，增强、负样本、数据偏差和捷径会决定模型实际学到什么。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"A⁺ 是 A 的裁剪正样本","rule":"τ=0.2","steps":"54.60/60.73","interpretation":"模型已经把正视图排在明显更高的位置"}},{"section":11,"evidence":{"setup":"按商品身份拆分的训练图和测试查询图","rule":"避免同一商品的近重复图跨训练与测试","steps":"换背景不换商品”和“换商品不换背景","interpretation":"模型利用了摄影棚捷径而不是商品身份"}}],"formulas":[{"id":"autoregressive-self-supervision","section":2,"formulaIndex":1,"symbols":[{"name":"L","meaning":"下标 AR 指定的整段自回归负对数损失","evidence":"L_AR 是整段文本的自回归损失"},{"name":"Σ","meaning":"把每个预测位置的损失相加","evidence":"Σ 把各位置损失相加"},{"name":"t","meaning":"当前要预测的 token 位置","evidence":"t 是当前预测位置"},{"name":"T","meaning":"输入序列的 token 总数","evidence":"T 是序列 token 数"},{"name":"log","meaning":"把真实 token 概率转换为可加损失的自然对数","evidence":"log 是自然对数"},{"name":"pθ","meaning":"参数 θ 的模型给出的条件概率","evidence":"参数 θ 的模型根据前缀赋给真实下一个 token 的条件概率"},{"name":"xₜ","meaning":"位置 t 的真实 token","evidence":"xₜ 是第 t 个真实 token"},{"name":"x<ₜ","meaning":"位置 t 之前的全部 token 前缀","evidence":"x<ₜ 是它之前的全部 token"}]},{"id":"masked-reconstruction-loss","section":3,"formulaIndex":1,"symbols":[{"name":"L","meaning":"下标 mask 指定的全部被遮位置总损失","evidence":"L_mask 是所有被遮位置的总损失"},{"name":"Σ","meaning":"只把被遮位置的损失相加","evidence":"只对其中的位置求和"},{"name":"i","meaning":"被遮位置集合中的某个位置","evidence":"i∈M 表示只对其中的位置求和"},{"name":"M","meaning":"本次训练中被遮住的位置集合","evidence":"M 是被遮位置集合"},{"name":"log","meaning":"对真实被遮内容概率取自然对数","evidence":"负对数同样惩罚给真实内容的低概率"},{"name":"pθ","meaning":"模型根据可见上下文恢复真实内容的概率","evidence":"pθ 是模型据此恢复 xᵢ 的概率"},{"name":"xᵢ","meaning":"位置 i 原本的真实内容","evidence":"xᵢ 是位置 i 原本的真实内容"},{"name":"x","meaning":"下标反斜线 M 指移除遮盖集合后的可见上下文","evidence":"x\\M 是拿掉 M 中内容后仍可见的上下文"}]},{"id":"infonce-positive-probability","section":4,"formulaIndex":1,"symbols":[{"name":"ℓ","meaning":"正样本匹配的负对数概率损失","evidence":"ℓ 是正样本的负对数概率损失"},{"name":"log","meaning":"对正样本归一化概率取自然对数","evidence":"负对数概率损失"},{"name":"exp","meaning":"把缩放相似度指数化以形成归一化权重","evidence":"exp 与分母求和把各候选分数转成概率"},{"name":"sim","meaning":"两个表示之间的相似度函数","evidence":"sim 计算两表示的相似度"},{"name":"a","meaning":"锚点样本 A 的表示","evidence":"a 是锚点样本 A 的表示"},{"name":"a⁺","meaning":"同一对象增强视图 A⁺ 的表示","evidence":"a⁺ 是同一商品增强视图 A⁺ 的表示"},{"name":"τ","meaning":"缩放相似度差异的温度参数","evidence":"τ 是温度，负责缩放相似度差异"},{"name":"Σ","meaning":"对正样本与所有候选负样本指数分数求和","evidence":"j 遍历正样本和候选负样本"},{"name":"j","meaning":"候选样本的遍历索引","evidence":"j 遍历正样本和候选负样本"}]},{"id":"vicreg-anti-collapse-objective","section":7,"formulaIndex":1,"symbols":[{"name":"L","meaning":"总损失及三个带下标的组成损失项","evidence":"L 是总损失"},{"name":"λ","meaning":"方差约束项的权重系数","evidence":"λ 与 μ 分别控制后两项强度"},{"name":"μ","meaning":"协方差去冗余项的权重系数","evidence":"λ 与 μ 分别控制后两项强度"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"自监督学习由原始数据及变换自动构造输入与明确训练目标。","evidence":"目标从数据自身产生"},"problem":{"answer":"它把海量无人工逐条标签的数据转化为可优化的监督信号。","evidence":"标签不是人工写的，但目标仍然明确"},"inputOutput":{"answer":"输入原始样本 z 和构造规则 q，输出模型输入 x 与自动目标 y。","evidence":"从中构造模型输入 x 和自动目标 y"},"mechanism":{"answer":"模型 fθ 根据 x 预测，损失 ℓ 比较预测与由同一数据生成的 y。","evidence":"由损失函数 ℓ 比较预测与 y"},"interpretation":{"answer":"有明确损失仍属于监督信号，差别在目标来源而非是否有目标。","evidence":"监督学习描述“有目标损失”"},"boundary":{"answer":"自监督是目标构造方式，无监督是更宽总称，二者不能简单等同。","evidence":"无监督则是更宽的总称"}},{"section":2,"definition":{"answer":"自回归目标用此前 token 作为输入，把下一个真实 token 当自动标签。","evidence":"自回归目标把每个位置都变成训练样本"},"problem":{"answer":"它从一段序列产生密集预测目标并同时训练生成接口。","evidence":"一段长度 T 的文本为何能提供 T−1 个目标"},"inputOutput":{"answer":"输入位置 t 前的前缀 x<ₜ，输出对真实 xₜ 的条件概率。","evidence":"输入前缀 自动目标"},"mechanism":{"answer":"因果遮罩阻止查看未来，对各位置真实 token 概率取负对数并求和。","evidence":"因果遮罩只允许读取此前 token"},"interpretation":{"answer":"损失下降表示模型更像训练分布地预测后续，不等于事实或行为正确。","evidence":"目标奖励“像数据分布”"},"boundary":{"answer":"预训练目标不直接奖励真实、无害或服从用户，需后训练和独立评测。","evidence":"不直接奖励真实、无害或服从当前用户"}},{"section":3,"definition":{"answer":"遮盖重建隐藏部分输入，再要求模型用仍可见的双向上下文恢复它。","evidence":"用双向证据恢复缺失部分"},"problem":{"answer":"它让模型从上下文学习可预测结构，而无需人工提供缺失内容标签。","evidence":"根据左右文恢复被遮 token"},"inputOutput":{"answer":"输入遮去集合 M 的文本或图像，输出每个被遮位置原始内容的概率。","evidence":"M 是被遮位置集合"},"mechanism":{"answer":"只对被遮位置计算负对数损失，并用可见上下文预测真实内容。","evidence":"只对其中的位置求和"},"interpretation":{"answer":"中等遮盖率常在任务难度与可预测证据之间取得更好平衡。","evidence":"在可预测证据与任务难度之间较平衡"},"boundary":{"answer":"过低会走局部复制捷径，过高会由不可预测细节主导，像素重建也可能偏离语义。","evidence":"重建像素还可能把容量花在颜色纹理"}},{"section":4,"definition":{"answer":"对比学习把同一对象的增强视图视为正对，并从候选负对中识别它。","evidence":"把正对从负对中识别出来"},"problem":{"answer":"它训练表示空间让同一对象靠近、不同对象相对远离。","evidence":"同一商品的匹配压力"},"inputOutput":{"answer":"输入锚点、正视图与负样本表示，输出正样本归一化概率和损失。","evidence":"正样本概率 54.60/60.73"},"mechanism":{"answer":"相似度除温度后指数化并在全部候选中归一化，再取正样本负对数。","evidence":"进入指数和归一化之前的缩放相似度"},"interpretation":{"answer":"本例正样本概率约 0.899、损失约 0.106，说明当前候选中排序较好。","evidence":"指数约 [54.60,4.48,1.65]"},"boundary":{"answer":"低温放大排序也放大标签错误，同类别 false negative 会施加错误排斥。","evidence":"实际上语义相近却被训练规则当成负例"}},{"section":5,"definition":{"answer":"预文本目标是从原始数据自动构造、用于迫使模型保留某类信息的训练任务。","evidence":"预文本目标决定模型被迫保留什么"},"problem":{"answer":"它解释相同数据为何因预测、遮盖或增强规则不同而学到不同表示。","evidence":"相同原始数据经过不同构造"},"inputOutput":{"answer":"输入原始文本图像音频与构造规则，输出用于下游迁移的参数或表示。","evidence":"原始数据 z"},"mechanism":{"answer":"右移保留顺序生成分布，遮盖保留可预测结构，增强声明不变变化。","evidence":"忽略被声明为不变的变化"},"interpretation":{"answer":"表示里保留什么由自动标签规则决定，并非自动中立或天然语义完整。","evidence":"“自动标签”并不中立"},"boundary":{"answer":"预文本效果必须通过线性探测、微调或提示等真实下游任务独立验收。","evidence":"下游任务独立验收"}},{"section":6,"definition":{"answer":"增强策略是把某种变化声明为不应改变目标语义的数据变换。","evidence":"增强策略实际定义了语义不变性"},"problem":{"answer":"它防止模型记忆像素捷径，同时也可能错误删除任务关键信息。","evidence":"裁掉语义主体"},"inputOutput":{"answer":"输入原始样本与增强规则，输出被视为同一对象的两种训练视图。","evidence":"随机裁剪可能把正样本变成错误正对"},"mechanism":{"answer":"训练拉近增强前后表示，迫使模型忽略增强改变的属性。","evidence":"颜色不决定身份"},"interpretation":{"answer":"若换背景不影响识别而换主体会改变结果，增强更可能抓住主体。","evidence":"模型会被迫认为背景与商品身份等价"},"boundary":{"answer":"裁剪、颜色、旋转、变速和回译是否保语义取决于具体任务。","evidence":"否定、实体或语气变化"}},{"section":7,"definition":{"answer":"表示坍缩是所有输入映射到近乎同一向量而失去区分信息。","evidence":"所有输入都输出近乎相同向量"},"problem":{"answer":"它解决无显式负样本的一致性目标可由常量表示轻易满足的问题。","evidence":"所有表示变成同一常数不是最优吗"},"inputOutput":{"answer":"输入同一样本的两视图，输出一致但仍有方差且维度不冗余的表示。","evidence":"两视图一致却不再含可区分信息"},"mechanism":{"answer":"停止梯度、动量教师或方差协方差约束制造不对称并阻止常量解。","evidence":"用停止梯度、教师动量更新"},"interpretation":{"answer":"训练损失低但表示方差、奇异值和邻居多样性塌陷说明仍发生坍缩。","evidence":"而非只看训练损失"},"boundary":{"answer":"没有显式负样本不等于无需防坍缩机制，不同方法的保护手段不同。","evidence":"没有显式负样本”不等于没有防坍缩机制"}},{"section":8,"definition":{"answer":"迁移评测用冻结、微调、少样本或检索协议测预训练表示的下游价值。","evidence":"迁移评测要区分冻结表示与端到端适配"},"problem":{"answer":"它避免用单一线性探测或预训练损失误判表示是否有用。","evidence":"线性探测差，是否说明预训练完全失败"},"inputOutput":{"answer":"输入固定数据划分、表示和调参预算，输出多协议及分切片下游指标。","evidence":"固定数据划分和调参预算"},"mechanism":{"answer":"线性探测测可分性，全量微调测适配性，冻结检索测距离空间。","evidence":"表示是否线性可分"},"interpretation":{"answer":"某协议差只表明对应访问方式受限，不足以推出预训练完全失败。","evidence":"低估可微调信息"},"boundary":{"answer":"协议受下游容量、提示、索引和预算影响，必须按来源难度与分布外切片。","evidence":"按来源、群体、难度与分布外样本切片"}},{"section":9,"definition":{"answer":"自监督数据治理覆盖来源许可、隐私、去重、污染和删除链路。","evidence":"规模优势把瓶颈转移到数据治理"},"problem":{"answer":"它防止自动目标规模化放大违法来源、隐私泄漏、偏见和评测污染。","evidence":"数据免费且无风险"},"inputOutput":{"answer":"输入原始数据及处理链，输出可追溯、可删除且覆盖被审计的训练集。","evidence":"记录来源、时间、处理链和删除能力"},"mechanism":{"answer":"通过许可审计、同意管理、去重、污染检测和群体覆盖检查治理。","evidence":"许可、隐私、同意、去重、污染"},"interpretation":{"answer":"评测集进入预训练语料会伪造迁移能力，必须作为污染处理。","evidence":"会伪造迁移能力"},"boundary":{"answer":"自监督只节省人工标签，不自动赋予数据授权或让目标符合产品价值。","evidence":"自监督只省标签，不免除治理"}},{"section":11,"definition":{"answer":"商品对比验收闭环从自动训练目标追踪到未见商品的真实检索表现。","evidence":"从训练目标一直追到未见商品上的真实检索结果"},"problem":{"answer":"它识别训练损失下降但模型只利用摄影棚背景捷径的失败。","evidence":"损失下降但模型只记住背景"},"inputOutput":{"answer":"输入商品级拆分图像，输出 top-k、表示方差及背景角度品类切片。","evidence":"输出是 top-k 商品检索结果"},"mechanism":{"answer":"先隔离商品、训练正对、冻结编码器检索，再做背景与主体反事实对照。","evidence":"随后冻结编码器"},"interpretation":{"answer":"换背景后同商品召回失败表示模型追踪摄影棚而非商品身份。","evidence":"说明模型利用了摄影棚捷径"},"boundary":{"answer":"该闭环只覆盖当前匹配任务，颜色文字或新拍摄域需重定义增强并复测。","evidence":"必须重新定义增强并复测对应切片"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分监督、无监督与自监督；计算一组对比学习概率；比较自回归、遮盖和对比目标；设计迁移与捷径验证。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>标签不是人工写的，但目标仍然明确<span class=\"dd-badge intuition\">定义</span></h2><p class=\"dd-lead\">把一句话右移一位，为什么就产生了监督信号？</p><p>给定原始样本 <code>z</code>，变换规则 <code>q</code> 从中构造模型输入 <code>x</code> 和自动目标 <code>y</code>；参数为 <code>θ</code> 的模型 <code>fθ</code> 根据 x 预测，再由损失函数 <code>ℓ</code> 比较预测与 y。文本下一个 token、被遮住片段、同一图片两种增强都可自动获得 y。监督学习描述“有目标损失”，自监督描述“目标从数据自身产生”；无监督则是更宽的总称。</p><div class=\"dd-note\"><b>贯穿例子：</b>三张商品图 A、B、C；A 的裁剪图 A⁺ 是正样本，B、C 是候选负样本。比较模型是否把同一商品的两种视图拉近。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>自回归目标把每个位置都变成训练样本<span class=\"dd-badge math\">预测未来</span></h2><p class=\"dd-lead\">一段长度 T 的文本为何能提供 T−1 个目标？</p><div class=\"dd-formula\">L<sub>AR</sub>=−Σ<sub>t=1…T</sub> log pθ(xₜ|x&lt;ₜ)</div><p><b>符号说明：</b><code>L_AR</code> 是整段文本的自回归损失；<code>T</code> 是序列 token 数，<code>t</code> 是当前预测位置，<code>Σ</code> 把各位置损失相加；<code>xₜ</code> 是第 t 个真实 token，<code>x&lt;ₜ</code> 是它之前的全部 token；<code>pθ(xₜ|x&lt;ₜ)</code> 是参数 θ 的模型根据前缀赋给真实下一个 token 的条件概率，<code>log</code> 是自然对数，前面的负号让真实 token 概率越小损失越大。</p><p>因果遮罩只允许读取此前 token。降低损失要求模型捕捉语法、主题、共现事实和代码结构，也训练出生成接口；但目标奖励“像数据分布”，不直接奖励真实、无害或服从当前用户。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>输入前缀</th><th>自动目标</th></tr></thead><tbody><tr><td>退款</td><td>已</td></tr><tr><td>退款 已</td><td>批准</td></tr><tr><td>退款 已 批准</td><td>。</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>遮盖重建用双向证据恢复缺失部分<span class=\"dd-badge math\">重建</span></h2><p class=\"dd-lead\">遮得太少或太多分别会发生什么？</p><div class=\"dd-formula\">L<sub>mask</sub>=−Σ<sub>i∈M</sub> log pθ(xᵢ|x<sub>M</sub>)</div><p><b>式中：</b><code>L_mask</code> 是所有被遮位置的总损失，<code>M</code> 是被遮位置集合，<code>i∈M</code> 表示只对其中的位置求和；<code>xᵢ</code> 是位置 i 原本的真实内容，<code>x\\M</code> 是拿掉 M 中内容后仍可见的上下文；<code>pθ</code> 是模型据此恢复 xᵢ 的概率，负对数同样惩罚给真实内容的低概率。</p><p>BERT 根据左右文恢复被遮 token；MAE 遮住图像块后重建。遮盖少时模型可靠局部复制，任务太容易；遮盖多时证据不足，损失被不可预测细节主导。中等遮盖率往往在可预测证据与任务难度之间较平衡，但最佳比例仍取决于模态和模型。重建像素还可能把容量花在颜色纹理，而非下游语义。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>遮盖率</th><th>主要风险</th><th>诊断</th></tr></thead><tbody><tr><td>低</td><td>局部捷径</td><td>扩大遮盖块/距离</td></tr><tr><td>中</td><td>通常平衡</td><td>迁移曲线</td></tr><tr><td>高</td><td>目标不确定</td><td>重建质量与语义探测分开看</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>手算对比学习：把正对从负对中识别出来<span class=\"dd-badge math\">InfoNCE</span></h2><p class=\"dd-lead\">温度和负样本怎样改变同一商品的匹配压力？</p><div class=\"dd-formula\">ℓ=−log exp(sim(a,a⁺)/τ) / Σ<sub>j</sub>exp(sim(a,j)/τ)</div><p><b>先读式子：</b><code>a</code> 是锚点样本 A 的表示，<code>a⁺</code> 是同一商品增强视图 A⁺ 的表示；<code>j</code> 遍历正样本和候选负样本，<code>sim</code> 计算两表示的相似度；<code>τ</code> 是温度，负责缩放相似度差异；<code>exp</code> 与分母求和把各候选分数转成概率，<code>ℓ</code> 是正样本的负对数概率损失。这里的 logit 是进入指数和归一化之前的缩放相似度。</p><p>沿用三张商品图 A、B、C：A⁺ 是 A 的裁剪正样本，B、C 是候选负样本。设相似度 s(A,A⁺)=0.8、s(A,B)=0.3、s(A,C)=0.1，τ=0.2。logit 为 [4,1.5,0.5]，指数约 [54.60,4.48,1.65]，正样本概率 54.60/60.73≈<b>0.899</b>，损失 −log0.899≈<b>0.106</b>。这说明在当前三个候选中，模型已经把正视图排在明显更高的位置。</p><p>较低温度放大排序差异，也放大错标正负对。批量和负样本来源改变任务难度；把同类别实例当负样本会产生 false negatives，也就是“实际上语义相近却被训练规则当成负例”。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：预文本目标决定模型被迫保留什么<span class=\"dd-badge intuition\">机制图</span></h2><p class=\"dd-lead\">相同原始数据经过不同构造，为何学到不同表示？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 315\" role=\"img\" aria-label=\"原始数据经过自回归遮盖和对比三种自监督任务形成表示\"><defs><marker id=\"ssla\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#778293\"/></marker></defs><rect x=\"24\" y=\"122\" width=\"130\" height=\"65\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"89\" y=\"150\" text-anchor=\"middle\" class=\"svg-t\">原始数据 z</text><text x=\"89\" y=\"171\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">文本 / 图像 / 音频</text><path d=\"M154,154 L230,65\" stroke=\"#778293\" marker-end=\"url(#ssla)\"/><path d=\"M154,154 L230,154\" stroke=\"#778293\" marker-end=\"url(#ssla)\"/><path d=\"M154,154 L230,244\" stroke=\"#778293\" marker-end=\"url(#ssla)\"/><rect x=\"235\" y=\"32\" width=\"190\" height=\"66\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"330\" y=\"59\" text-anchor=\"middle\" class=\"svg-t\">右移：预测下一个</text><text x=\"330\" y=\"82\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">保留顺序与生成分布</text><rect x=\"235\" y=\"121\" width=\"190\" height=\"66\" rx=\"9\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"330\" y=\"148\" text-anchor=\"middle\" class=\"svg-t\">遮盖：恢复缺失块</text><text x=\"330\" y=\"171\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">保留上下文可预测结构</text><rect x=\"235\" y=\"211\" width=\"190\" height=\"66\" rx=\"9\" fill=\"#21252d\" stroke=\"#5d9f79\"/><text x=\"330\" y=\"238\" text-anchor=\"middle\" class=\"svg-t\">增强：识别同一对象</text><text x=\"330\" y=\"261\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">忽略被声明为不变的变化</text><path d=\"M425,65 L505,140\" stroke=\"#778293\" marker-end=\"url(#ssla)\"/><path d=\"M425,154 L505,154\" stroke=\"#778293\" marker-end=\"url(#ssla)\"/><path d=\"M425,244 L505,170\" stroke=\"#778293\" marker-end=\"url(#ssla)\"/><rect x=\"510\" y=\"115\" width=\"196\" height=\"79\" rx=\"9\" fill=\"#21252d\" stroke=\"#cf7c72\"/><text x=\"608\" y=\"143\" text-anchor=\"middle\" class=\"svg-t\">参数 / 表示</text><text x=\"608\" y=\"165\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">线性探测 · 微调 · 提示</text><text x=\"608\" y=\"183\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">下游任务独立验收</text></svg><figcaption>图 1　“自动标签”并不中立：构造规则定义模型应预测、恢复或忽略的信息。</figcaption></figure></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>增强策略实际定义了语义不变性<span class=\"dd-badge eng\">捷径</span></h2><p class=\"dd-lead\">为什么商品图随机裁剪可能把正样本变成错误正对？</p><p>若裁剪只剩品牌背景而丢掉商品，模型会被迫认为背景与商品身份等价；医学图旋转、数字翻转或音频变速也可能改变标签。反之，增强过弱时模型可利用颜色直方图、文件压缩或边框等捷径。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>增强</th><th>声明的不变性</th><th>破坏风险</th></tr></thead><tbody><tr><td>随机裁剪</td><td>局部视图同对象</td><td>裁掉语义主体</td></tr><tr><td>颜色抖动</td><td>颜色不决定身份</td><td>颜色是任务标签</td></tr><tr><td>文本回译</td><td>改写保持语义</td><td>否定、实体或语气变化</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>无负样本方法用不对称结构防止坍缩<span class=\"dd-badge math\">自蒸馏</span></h2><p class=\"dd-lead\">若只让两种视图靠近，所有表示变成同一常数不是最优吗？</p><p>是的，朴素一致性损失允许“表示坍缩”——所有输入都输出近乎相同向量，虽然两视图一致却不再含可区分信息。BYOL、DINO 等用停止梯度、教师动量更新、中心化/锐化或预测头制造不对称；VICReg 等显式约束方差与协方差。</p><div class=\"dd-formula\">L=L<sub>invariance</sub>+λL<sub>variance</sub>+μL<sub>covariance</sub></div><p><b>式中：</b><code>L</code> 是总损失，<code>L_invariance</code> 拉近同一样本的两种视图，<code>L_variance</code> 防止每个表示维度失去变化，<code>L_covariance</code> 减少不同维度携带重复信息；<code>λ</code> 与 <code>μ</code> 分别控制后两项强度。“没有显式负样本”不等于没有防坍缩机制。可监控表示方差、奇异值谱（各主要表示方向还剩多少变化强度）和最近邻多样性，而非只看训练损失。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>迁移评测要区分冻结表示与端到端适配<span class=\"dd-badge eng\">验收</span></h2><p class=\"dd-lead\">线性探测差，是否说明预训练完全失败？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>协议</th><th>主要测什么</th><th>局限</th></tr></thead><tbody><tr><td>线性探测</td><td>表示是否线性可分</td><td>低估可微调信息</td></tr><tr><td>全量微调</td><td>初始化可适配性</td><td>混入下游容量与预算</td></tr><tr><td>少样本/提示</td><td>数据效率与接口能力</td><td>方差大、提示敏感</td></tr><tr><td>冻结检索</td><td>距离空间质量</td><td>依赖索引与度量</td></tr></tbody></table></div><p>所有协议必须固定数据划分和调参预算，并按来源、群体、难度与分布外样本切片。预训练 loss 只能用于过程监控，不能替代迁移证据。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>规模优势把瓶颈转移到数据治理<span class=\"dd-badge eng\">边界</span></h2><p class=\"dd-lead\">不需要人工逐条标注，是否意味着数据免费且无风险？</p><p>原始数据仍涉及许可、隐私、同意、去重、污染、恶意内容和群体覆盖。自动目标会把数据中的偏见与泄漏一起放大；评测集出现在预训练语料中会伪造迁移能力。需要记录来源、时间、处理链和删除能力。</p><div class=\"dd-note warn\"><b>自监督只省标签，不免除治理。</b>训练目标来自数据，不代表数据拥有合法授权，也不代表目标与产品价值一致。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">真正的问题不是“有没有标签”，而是标签如何被构造。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>自监督没有监督信号</td><td>目标由数据变换自动构造</td></tr><tr><td>预训练损失低就会下游好</td><td>代理目标可能错位或走捷径</td></tr><tr><td>增强越强越好</td><td>增强定义不变性，可能破坏语义</td></tr><tr><td>对比学习负样本越多越好</td><td>false negative 与分布同样重要</td></tr><tr><td>无负样本方法无需防坍缩</td><td>通常依靠不对称或显式方差约束</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>监督学习、损失函数、表示学习</td></tr><tr><td><b>本页核心</b></td><td>自回归、遮盖、InfoNCE、坍缩</td></tr><tr><td>架构</td><td>LLM、BERT、CLIP、MAE</td></tr><tr><td>治理</td><td>预训练、训练数据治理、评测污染</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">11</span>完整示例：同一商品对比目标的验收闭环<span class=\"dd-badge eng\">端到端示例</span></h2><p class=\"dd-lead\">算出0.106的训练损失后，怎样证明表示真的可用于商品匹配？</p><p>这里的“验收闭环”是从训练目标一直追到未见商品上的真实检索结果，解决“损失下降但模型只记住背景”的错判。输入是按商品身份拆分的训练图和测试查询图，输出是 top-k 商品检索结果、表示方差以及背景/角度/品类切片指标。</p><p>先固定商品级拆分，避免同一商品的近重复图跨训练与测试；再训练 A—A⁺ 正对，记录相似度和表示方差；随后冻结编码器，在从未见过的商品上做 top-k 检索，并按背景、角度和品类切片。最后用“换背景不换商品”和“换商品不换背景”的反事实对照，确认模型追踪主体而非摄影棚捷径。</p><div class=\"dd-note warn\"><b>结果怎样解释：</b>若平均 top-k 很高，但换背景后同一商品无法召回，说明模型利用了摄影棚捷径而不是商品身份。这个闭环只验证当前商品匹配任务；换到细粒度颜色、文字或新拍摄域时，必须重新定义增强并复测对应切片。</div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">12</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>选择原始数据与期望不变性</li><li>构造预测/遮盖/视图目标</li><li>优化代理损失并防止坍缩</li><li>冻结或微调迁移到下游</li><li>用真实切片排查捷径</li><li>审计来源、污染与目标错位</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">13</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>自监督为什么仍有监督？</li><li>算例中正样本概率约多少？</li><li>遮盖率太低的主要风险？</li><li>增强为什么不是中立预处理？</li><li>无负样本方法如何避免常数表示？</li><li>假设“自监督学习：让数据自己产生训练目标”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>输入和目标由数据自身及变换自动生成，仍有明确损失。</li><li>exp(4)/(exp4+exp1.5+exp0.5)≈0.899。</li><li>任务过易，模型利用局部复制等捷径。</li><li>它声明哪些变化不应改变语义，错误增强会注入错误不变性。</li><li>依靠停止梯度、动量教师、不对称头或方差/协方差约束。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1810.04805\" target=\"_blank\" rel=\"noopener\">BERT</a>：遮盖语言建模</li><li><a href=\"https://arxiv.org/abs/2002.05709\" target=\"_blank\" rel=\"noopener\">A Simple Framework for Contrastive Learning of Visual Representations</a>：SimCLR 与增强</li><li><a href=\"https://arxiv.org/abs/2006.07733\" target=\"_blank\" rel=\"noopener\">Bootstrap Your Own Latent</a>：无负样本自蒸馏</li><li><a href=\"https://arxiv.org/abs/2104.14294\" target=\"_blank\" rel=\"noopener\">Emerging Properties in Self-Supervised Vision Transformers</a>：DINO</li><li><a href=\"https://arxiv.org/abs/2111.06377\" target=\"_blank\" rel=\"noopener\">Masked Autoencoders Are Scalable Vision Learners</a>：视觉遮盖重建</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
